:13:\"allow-dismiss\";b:0;}i:7;a:9:{s:4:\"slug\";s:42:\"orders-list-empty-body-table-rate-shipping\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:19:\"table-rate-shipping\";s:4:\"icon\";s:101:\"https://woocommerce.com/wp-content/uploads/2012/07/Table_Rate_Shipping_icon-marketplace-160x160-2.png\";s:5:\"title\";s:19:\"Table Rate Shipping\";s:4:\"copy\";s:123:\"Advanced, flexible shipping. Define multiple shipping rates based on location, price, weight, shipping class or item count.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:53:\"https://woocommerce.com/products/table-rate-shipping/\";s:9:\"is_pinned\";b:1;}i:8;a:9:{s:4:\"slug\";s:56:\"orders-list-empty-body-conditional-shipping-and-payments\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:33:\"conditional-shipping-and-payments\";s:4:\"icon\";s:111:\"https://woocommerce.com/wp-content/uploads/2015/03/Conditional_Shipping_Payments_icon-marketplace-160x160-1.png\";s:5:\"title\";s:33:\"Conditional Shipping and Payments\";s:4:\"copy\";s:91:\"Use conditional logic to restrict the shipping and payment options available on your store.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:67:\"https://woocommerce.com/products/conditional-shipping-and-payments/\";s:9:\"is_pinned\";b:1;}i:9;a:9:{s:4:\"slug\";s:40:\"orders-list-empty-body-shipment-tracking\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:17:\"shipment-tracking\";s:4:\"icon\";s:99:\"https://woocommerce.com/wp-content/uploads/2012/05/Shipment_Tracking_icon-marketplace-160x160-2.png\";s:5:\"title\";s:17:\"Shipment Tracking\";s:4:\"copy\";s:49:\"Add shipment tracking information to your orders.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:51:\"https://woocommerce.com/products/shipment-tracking/\";s:9:\"is_pinned\";b:1;}i:10;a:8:{s:4:\"slug\";s:31:\"orders-list-empty-body-shipping\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:8:\"shipping\";s:4:\"icon\";s:76:\"https://woocommerce.com/wp-content/uploads/2017/06/icon-shipping_160x160.png\";s:5:\"title\";s:20:\"WooCommerce Shipping\";s:4:\"copy\";s:473:\"WooCommerce Shipping is a free label-printing and fulfillment extension built into WooCommerce that lets store owners buy and print USPS, UPS, DHL Express, and FedEx labels directly from their dashboard. It uses Woo\'s own carrier accounts for discounted commercial rates, so merchants don\'t need separate accounts with each carrier. It compares live label rates, generates tracking numbers automatically, and supports split shipments. All shipments are 100% carbon neutral.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:42:\"https://woocommerce.com/products/shipping/\";}i:11;a:8:{s:4:\"slug\";s:46:\"orders-list-empty-body-shipstation-integration\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:23:\"shipstation-integration\";s:4:\"icon\";s:73:\"https://woocommerce.com/wp-content/uploads/2012/08/ShipStation-Icon-1.png\";s:5:\"title\";s:11:\"ShipStation\";s:4:\"copy\";s:113:\"Ship your WooCommerce orders with confidence, save on top carriers, and automate your processes with ShipStation.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:57:\"https://woocommerce.com/products/shipstation-integration/\";}i:12;a:8:{s:4:\"slug\";s:33:\"orders-list-empty-body-royal-mail\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:10:\"royal-mail\";s:4:\"icon\";s:75:\"https://woocommerce.com/wp-content/uploads/2013/04/woo-RoyalMail-sd9zwy.png\";s:5:\"title\";s:26:\"Royal Mail Shipping Method\";s:4:\"copy\";s:50:\"Offer Royal Mail shipping rates to your customers.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:44:\"https://woocommerce.com/products/royal-mail/\";}i:13;a:8:{s:4:\"slug\";s:44:\"orders-list-empty-body-fedex-shipping-module\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:21:\"fedex-shipping-module\";s:4:\"icon\";s:71:\"https://woocommerce.com/wp-content/uploads/2013/01/woo-FedEx-auxjb7.png\";s:5:\"title\";s:21:\"FedEx Shipping Method\";s:4:\"copy\";s:92:\"Get shipping rates from the FedEx API which handles both domestic and international parcels.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:55:\"https://woocommerce.com/products/fedex-shipping-module/\";}i:14;a:8:{s:4:\"slug\";s:50:\"orders-list-empty-body-canada-post-shipping-method\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:27:\"canada-post-shipping-method\";s:4:\"icon\";s:76:\"https://woocommerce.com/wp-content/uploads/2013/01/woo-CanadaPost-fjlcfq.png\";s:5:\"title\";s:27:\"Canada Post Shipping Method\";s:4:\"copy\";s:106:\"Get shipping rates from the Canada Post Ratings API which handles both domestic and international parcels.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:61:\"https://woocommerce.com/products/canada-post-shipping-method/\";}i:15;a:8:{s:4:\"slug\";s:50:\"orders-list-empty-body-shipping-multiple-addresses\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:27:\"shipping-multiple-addresses\";s:4:\"icon\";s:109:\"https://woocommerce.com/wp-content/uploads/2012/09/Shipping_Multiple_Addresses_icon-marketplace-160x160-2.png\";s:5:\"title\";s:27:\"Shipping Multiple Addresses\";s:4:\"copy\";s:86:\"Allow your customers to ship individual items in a single order to multiple addresses.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:61:\"https://woocommerce.com/products/shipping-multiple-addresses/\";}i:16;a:8:{s:4:\"slug\";s:58:\"orders-list-empty-body-role-based-payment-shipping-methods\";s:7:\"context\";s:22:\"orders-list-empty-body\";s:7:\"product\";s:35:\"role-based-payment-shipping-methods\";s:4:\"icon\";s:83:\"https://woocommerce.com/wp-content/uploads/2012/08/role-based-methods-copy@0.5x.png\";s:5:\"title\";s:37:\"Role-Based Payment / Shipping Methods\";s:4:\"copy\";s:76:\"Limit different user roles to specific payment methods and shipping methods.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:69:\"https://woocommerce.com/products/role-based-payment-shipping-methods/\";}i:17;a:9:{s:4:\"slug\";s:42:\"product-edit-meta-tab-body-product-add-ons\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:15:\"product-add-ons\";s:4:\"icon\";s:96:\"https://woocommerce.com/wp-content/uploads/2013/05/Product_Addons_icon-marketplace-160x160-2.png\";s:5:\"title\";s:15:\"Product Add-Ons\";s:4:\"copy\";s:94:\"Offer add-ons like gift wrapping, special messages or other special options for your products.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:49:\"https://woocommerce.com/products/product-add-ons/\";s:9:\"is_pinned\";b:1;}i:18;a:9:{s:4:\"slug\";s:42:\"product-edit-meta-tab-body-product-bundles\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:15:\"product-bundles\";s:4:\"icon\";s:97:\"https://woocommerce.com/wp-content/uploads/2012/07/Product_Bundles_icon-marketplace-160x160-2.png\";s:5:\"title\";s:15:\"Product Bundles\";s:4:\"copy\";s:84:\"Offer personalized product bundles, bulk discount packages, and assembled products.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:49:\"https://woocommerce.com/products/product-bundles/\";s:9:\"is_pinned\";b:1;}i:19;a:9:{s:4:\"slug\";s:47:\"product-edit-meta-tab-body-woocommerce-bookings\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:20:\"woocommerce-bookings\";s:4:\"icon\";s:90:\"https://woocommerce.com/wp-content/uploads/2014/05/Bookings_icon-marketplace-160x160-1.png\";s:5:\"title\";s:20:\"WooCommerce Bookings\";s:4:\"copy\";s:497:\"WooCommerce Bookings is the official WooCommerce extension that lets store owners sell appointments, reservations, rentals, or classes with bookable time or date slots. It supports fixed time slots or flexible ranges, group and individual pricing, and resources — staff, rooms, or equipment — each with its own availability to prevent double-booking. It syncs with Google Calendar and works with any WooCommerce payment gateway. It\'s a paid annual extension with a 30-day money-back guarantee.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:54:\"https://woocommerce.com/products/woocommerce-bookings/\";s:9:\"is_pinned\";b:1;}i:20;a:9:{s:4:\"slug\";s:52:\"product-edit-meta-tab-body-woocommerce-subscriptions\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:25:\"woocommerce-subscriptions\";s:4:\"icon\";s:99:\"https://woocommerce.com/wp-content/uploads/2012/09/Woo_Subscriptions_icon-marketplace-160x160-2.png\";s:5:\"title\";s:25:\"WooCommerce Subscriptions\";s:4:\"copy\";s:514:\"WooCommerce Subscriptions is a WooCommerce extension that lets customers subscribe to your products or services and pay on a weekly, monthly, or annual basis. It integrates with over 25 payment gateways for automatic recurring payments and supports automatic rebilling on failed subscription payments. Subscribers can manage their own plan — upgrading, downgrading, suspending, or canceling — and update their shipping address or payment method. It\'s a paid annual extension with a 30-day money-back guarantee.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:59:\"https://woocommerce.com/products/woocommerce-subscriptions/\";s:9:\"is_pinned\";b:1;}i:21;a:9:{s:4:\"slug\";s:45:\"product-edit-meta-tab-body-composite-products\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:18:\"composite-products\";s:4:\"icon\";s:100:\"https://woocommerce.com/wp-content/uploads/2013/06/Composite_Products_icon-marketplace-160x160-1.png\";s:5:\"title\";s:18:\"Composite Products\";s:4:\"copy\";s:85:\"Create product kit builders and custom product configurators using existing products.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:52:\"https://woocommerce.com/products/composite-products/\";s:9:\"is_pinned\";b:1;}i:22;a:8:{s:4:\"slug\";s:56:\"product-edit-meta-tab-body-variation-swatches-and-photos\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:29:\"variation-swatches-and-photos\";s:4:\"icon\";s:85:\"https://woocommerce.com/wp-content/uploads/2012/06/Variation_Swatches_Photos_Icon.png\";s:5:\"title\";s:29:\"Variation Swatches and Photos\";s:4:\"copy\";s:73:\"Show color and image swatches instead of dropdowns for variable products.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:63:\"https://woocommerce.com/products/variation-swatches-and-photos/\";}i:23;a:8:{s:4:\"slug\";s:48:\"product-edit-meta-tab-body-woocommerce-360-image\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:21:\"woocommerce-360-image\";s:4:\"icon\";s:75:\"https://woocommerce.com/wp-content/uploads/2014/10/Kestrel-product-logo.png\";s:5:\"title\";s:11:\"360º Image\";s:4:\"copy\";s:82:\"Add responsive, touch‑enabled 360º product rotations to WooCommerce in minutes.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:55:\"https://woocommerce.com/products/woocommerce-360-image/\";}i:24;a:8:{s:4:\"slug\";s:42:\"product-edit-meta-tab-body-dynamic-pricing\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:15:\"dynamic-pricing\";s:4:\"icon\";s:89:\"https://woocommerce.com/wp-content/uploads/2012/02/Dynamic_Pricing_Marketplace_Icon-3.png\";s:5:\"title\";s:15:\"Dynamic Pricing\";s:4:\"copy\";s:48:\"Bulk discounts, role-based pricing and much more\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:49:\"https://woocommerce.com/products/dynamic-pricing/\";}i:25;a:8:{s:4:\"slug\";s:78:\"product-edit-meta-tab-body-buy-once-or-subscribe-for-woocommerce-subscriptions\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:51:\"buy-once-or-subscribe-for-woocommerce-subscriptions\";s:4:\"icon\";s:71:\"https://woocommerce.com/wp-content/uploads/2022/02/bos-product-icon.png\";s:5:\"title\";s:51:\"Buy Once or Subscribe for WooCommerce Subscriptions\";s:4:\"copy\";s:259:\"Offer one-time purchases and recurring subscription plans side by side on the same product page — no duplicate listings, no complex setup. Increase recurring revenue, reduce churn, and give every type of customer exactly the flexibility they\'re looking for.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:85:\"https://woocommerce.com/products/buy-once-or-subscribe-for-woocommerce-subscriptions/\";}i:26;a:8:{s:4:\"slug\";s:81:\"product-edit-meta-tab-body-custom-cancelation-rules-for-woocommerce-subscriptions\";s:7:\"context\";s:26:\"product-edit-meta-tab-body\";s:7:\"product\";s:54:\"custom-cancelation-rules-for-woocommerce-subscriptions\";s:4:\"icon\";s:65:\"https://woocommerce.com/wp-content/uploads/2022/04/CCR-icon-3.png\";s:5:\"title\";s:54:\"Custom Cancelation Rules for WooCommerce Subscriptions\";s:4:\"copy\";s:99:\"Minimum commitment periods, cancellation windows, notice periods, cancelation fees, or settlements.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:88:\"https://woocommerce.com/products/custom-cancelation-rules-for-woocommerce-subscriptions/\";}}s:7:\"updated\";i:1789943892;}','off');
