INSERT INTO `wp_posts` VALUES (49,1,'2026-09-22 23:38:32','2026-09-23 04:38:32','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"}},\"border\":{\"width\":\"2px\",\"color\":\"#1f6f50\",\"radius\":\"16px\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-border-color\" style=\"border-color:#1f6f50;border-width:2px;border-radius:16px;padding-top:1.5rem;padding-right:1.5rem;padding-bottom:1.5rem;padding-left:1.5rem\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Paga tu pedido con código QR</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Escanea este código con DeUna o con la app de tu banco para pagar tu pedido. Cuando confirmemos el pago, lo prepararemos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":82,\"width\":\"260px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://myecomerce.local/wp-content/uploads/2026/09/codigo-qr-pago-1.png\" alt=\"Código QR para pagar el pedido\" class=\"wp-image-82\" style=\"width:260px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->','Código QR de pago','','publish','closed','closed','','codigo-qr-de-pago','','','2026-09-23 00:57:31','2026-09-23 05:57:31','',0,'http://myecomerce.local/codigo-qr-de-pago/',0,'wp_block','',0);
INSERT INTO `wp_posts` VALUES (50,1,'2026-09-22 23:38:33','2026-09-23 04:38:33','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"twentytwentyfive\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\"><!-- wp:woocommerce/order-confirmation-status {\"fontSize\":\"large\"} /-->\n\n<!-- wp:block {\"ref\":49} /-->\n\n	<!-- wp:woocommerce/order-confirmation-summary /--><!-- wp:woocommerce/order-confirmation-create-account --><div class=\"wp-block-woocommerce-order-confirmation-create-account alignwide\">\n					<!-- wp:heading {\"level\":3} -->\n                    <h3 class=\"wp-block-heading\">Crear una cuenta con Mercadito Bit a Bit</h3>\n					<!-- /wp:heading -->\n					<!-- wp:list {\"className\":\"is-style-checkmark-list\"} -->\n					<ul class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n                    <li>Compras futuras más rápidas</li>\n                    <!-- /wp:list-item -->\n                    <!-- wp:list-item -->\n                    <li>Guardar la información de pago de forma segura</li>\n                    <!-- /wp:list-item -->\n                    <!-- wp:list-item -->\n                    <li>Seguimiento de pedidos e historial de compras</li>\n                    <!-- /wp:list-item --></ul>\n                    <!-- /wp:list -->\n                    </div><!-- /wp:woocommerce/order-confirmation-create-account -->\n\n	<!-- wp:woocommerce/order-confirmation-totals-wrapper {\"align\":\"wide\"} -->\n	<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\"}},\"metadata\":{\"patternName\":\"woocommerce/order-confirmation-totals-heading\"}} --><h2 class=\"wp-block-heading\" style=\"font-size:24px\">Detalles del pedido</h2><!-- /wp:heading -->\n\n	<!-- wp:woocommerce/order-confirmation-totals {\"lock\":{\"remove\":true}} /-->\n	<!-- /wp:woocommerce/order-confirmation-totals-wrapper -->\n\n	<!-- wp:woocommerce/order-confirmation-downloads-wrapper {\"align\":\"wide\"} -->\n	<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\"}},\"metadata\":{\"patternName\":\"woocommerce/order-confirmation-downloads-heading\"}} --><h2 class=\"wp-block-heading\" style=\"font-size:24px\">Descargas</h2><!-- /wp:heading -->\n\n	<!-- wp:woocommerce/order-confirmation-downloads {\"lock\":{\"remove\":true}} /-->\n	<!-- /wp:woocommerce/order-confirmation-downloads-wrapper -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"wc-block-order-confirmation-address-wrapper\"} -->\n	<div class=\"wp-block-columns alignwide wc-block-order-confirmation-address-wrapper\">\n		<!-- wp:column -->\n		<div class=\"wp-block-column\">\n			<!-- wp:woocommerce/order-confirmation-shipping-wrapper {\"align\":\"wide\"} -->\n			<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\"}},\"metadata\":{\"patternName\":\"woocommerce/order-confirmation-shipping-heading\"}} --><h2 class=\"wp-block-heading\" style=\"font-size:24px\">Dirección de envío</h2><!-- /wp:heading -->\n\n			<!-- wp:woocommerce/order-confirmation-shipping-address {\"lock\":{\"remove\":true}} /-->\n			<!-- /wp:woocommerce/order-confirmation-shipping-wrapper -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column -->\n		<div class=\"wp-block-column\">\n			<!-- wp:woocommerce/order-confirmation-billing-wrapper {\"align\":\"wide\"} -->\n			<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\"}},\"metadata\":{\"patternName\":\"woocommerce/order-confirmation-billing-heading\"}} --><h2 class=\"wp-block-heading\" style=\"font-size:24px\">Dirección de facturación</h2><!-- /wp:heading -->\n\n			<!-- wp:woocommerce/order-confirmation-billing-address {\"lock\":{\"remove\":true}} /-->\n			<!-- /wp:woocommerce/order-confirmation-billing-wrapper -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n\n	<!-- wp:woocommerce/order-confirmation-additional-fields-wrapper {\"align\":\"wide\"} -->\n	<!-- wp:heading {\"level\":2,\"style\":{\"typography\":{\"fontSize\":\"24px\"}},\"metadata\":{\"patternName\":\"woocommerce/order-confirmation-additional-fields-heading\"}} --><h2 class=\"wp-block-heading\" style=\"font-size:24px\">Información adicional</h2><!-- /wp:heading -->\n	<!-- wp:woocommerce/order-confirmation-additional-fields /-->\n	<!-- /wp:woocommerce/order-confirmation-additional-fields-wrapper -->\n\n	<!-- wp:woocommerce/order-confirmation-additional-information /-->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"twentytwentyfive\"} /-->','Confirmación del pedido','La plantilla de confirmación del pedido sirve como recibo y confirmación de una compra correcta. Incluye un resumen de los artículos del pedido, envío, facturación y totales.','publish','closed','closed','','order-confirmation','','','2026-09-22 23:38:33','2026-09-23 04:38:33','',0,'http://myecomerce.local/order-confirmation/',0,'wp_template','',0);
INSERT INTO `wp_posts` VALUES (51,1,'2026-09-22 23:39:18','2026-09-23 04:39:18','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"3rem\",\"bottom\":\"2rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:3rem;padding-bottom:2rem\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Productos de nuestra tierra, a un clic</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">En Mercadito Bit a Bit encuentras café, chocolate, miel y artesanías de pequeños productores. Elige lo que te gusta, revisa tu carrito y haz tu pedido en pocos pasos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"#productos\">Ver productos</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" href=\"/carrito/\">Ver mi carrito</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"1rem\",\"bottom\":\"2rem\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:1rem;padding-bottom:2rem\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Comprar es así de fácil</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">1. Elige</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Toca «Añadir al carrito» en el producto que quieras.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">2. Revisa</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">En el carrito cambias cantidades, quitas productos y ves el total.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">3. Paga</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Escribe tus datos y paga con código QR o contra entrega.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"anchor\":\"productos\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"1rem\",\"bottom\":\"3rem\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1100px\"}} -->\n<div id=\"productos\" class=\"wp-block-group\" style=\"padding-top:1rem;padding-bottom:3rem\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Nuestros productos</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-collection {\"queryId\":7,\"query\":{\"perPage\":5,\"pages\":0,\"offset\":0,\"postType\":\"product\",\"order\":\"asc\",\"orderBy\":\"title\",\"search\":\"\",\"exclude\":[],\"inherit\":false,\"taxQuery\":[],\"isProductCollectionBlock\":true,\"featured\":false,\"woocommerceOnSale\":false,\"woocommerceStockStatus\":[\"instock\",\"outofstock\",\"onbackorder\"],\"woocommerceAttributes\":[],\"woocommerceHandPickedProducts\":[]},\"tagName\":\"div\",\"displayLayout\":{\"type\":\"flex\",\"columns\":3