INSERT INTO `wp_posts` VALUES (68,1,'2026-09-23 00:06:08','2026-09-23 05:06:08','<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"1.5rem\",\"bottom\":\"1.5rem\",\"left\":\"1.5rem\",\"right\":\"1.5rem\"}},\"border\":{\"width\":\"2px\",\"color\":\"#1f6f50\",\"radius\":\"16px\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-border-color\" style=\"border-color:#1f6f50;border-width:2px;border-radius:16px;padding-top:1.5rem;padding-right:1.5rem;padding-bottom:1.5rem;padding-left:1.5rem\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":3} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Paga tu pedido con código QR</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Escanea este código con DeUna o con la app de tu banco para pagar tu pedido. Cuando confirmemos el pago, lo prepararemos.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":48,\"width\":\"260px\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://myecomerce.local/wp-content/uploads/2026/09/codigo-qr-pago.png\" alt=\"Código QR para pagar el pedido\" class=\"wp-image-48\" style=\"width:260px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->','Código QR de pago','','inherit','closed','closed','','49-revision-v1','','','2026-09-23 00:06:08','2026-09-23 05:06:08','',49,'http://myecomerce.local/?p=68',0,'revision','',0);
